
// === Module: src/utils/prng.js ===
/**
 * Mulberry32 PRNG (Pseudo-Random Number Generator)
 * สร้างตัวเลขสุ่มแบบ deterministic ที่ให้ผลลัพธ์เหมือนเดิมทุกครั้งเมื่อใช้ seed เดิม
 */
class PRNG {
  /**
   * @param {number|string} seed
   */
  constructor(seed = 123456789) {
    if (typeof seed === 'string') {
      let hash = 0;
      for (let i = 0; i < seed.length; i++) {
        hash = Math.imul(31, hash) + seed.charCodeAt(i) | 0;
      }
      this.seed = hash >>> 0;
    } else {
      this.seed = (seed >>> 0) || 123456789;
    }
  }

  /**
   * คืนค่าสุ่มทศนิยมระหว่าง [0, 1)
   * @returns {number}
   */
  next() {
    let t = (this.seed += 0x6D2B79F5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /**
   * สุ่มเลขจำนวนเต็มระหว่าง [min, max]
   * @param {number} min 
   * @param {number} max 
   * @returns {number}
   */
  nextInt(min, max) {
    return Math.floor(this.next() * (max - min + 1)) + min;
  }

  /**
   * สุ่มเลือกหนึ่งชิ้นจาก array
   * @template T
   * @param {T[]} array 
   * @returns {T}
   */
  choice(array) {
    if (!array || array.length === 0) return null;
    return array[this.nextInt(0, array.length - 1)];
  }

  /**
   * สับเปลี่ยนตำแหน่งใน array (Fisher-Yates shuffle แบบ deterministic)
   * @template T
   * @param {T[]} array 
   * @returns {T[]} อาเรย์ใหม่ที่สับเปลี่ยนแล้ว
   */
  shuffle(array) {
    const copy = [...array];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  }
}


// === Module: src/utils/thai-date.js ===
/**
 * ยูทิลิตี้จัดการและจัดรูปแบบวันเวลาภาษาไทย (พ.ศ. และเวลา 24 ชม.)
 * เขตเวลา Asia/Bangkok (+07:00)
 */

const THAI_MONTHS_SHORT = [
  'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.',
  'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'
];

const THAI_MONTHS_FULL = [
  'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
  'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
];

const THAI_DAYS_SHORT = ['อา.', 'จ.', 'อ.', 'พ.', 'พฤ.', 'ศ.', 'ส.'];
const THAI_DAYS_FULL = [
  'วันอาทิตย์', 'วันจันทร์', 'วันอังคาร', 'วันพุธ', 'วันพฤหัสบดี', 'วันศุกร์', 'วันเสาร์'
];

/**
 * จัดรูปแบบวันที่เป็นภาษาไทย พ.ศ. เช่น "24 ต.ค. 2569"
 * @param {string|Date} dateInput 
 * @param {boolean} fullMonth 
 * @returns {string}
 */
function formatThaiDate(dateInput, fullMonth = false) {
  if (!dateInput) return '-';
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return '-';

  const day = d.getDate();
  const month = fullMonth ? THAI_MONTHS_FULL[d.getMonth()] : THAI_MONTHS_SHORT[d.getMonth()];
  const yearBE = d.getFullYear() + 543;

  return `${day} ${month} ${yearBE}`;
}

/**
 * จัดรูปแบบเวลา 24 ชม. เช่น "09:00 น." หรือ "09:00 - 12:00 น."
 * @param {string|Date} dateInput 
 * @returns {string}
 */
function formatThaiTime(dateInput) {
  if (!dateInput) return '-';
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return '-';

  const hours = String(d.getHours()).padStart(2, '0');
  const minutes = String(d.getMinutes()).padStart(2, '0');
  return `${hours}:${minutes} น.`;
}

/**
 * จัดรูปแบบช่วงเวลา เช่น "09:00 - 12:00 น."
 * @param {string|Date} startInput 
 * @param {string|Date} endInput 
 * @returns {string}
 */
function formatThaiTimeRange(startInput, endInput) {
  if (!startInput || !endInput) return '-';
  if (typeof startInput === 'string' && /^\d{1,2}:\d{2}/.test(startInput) && !startInput.includes('T')) {
    const endStr = typeof endInput === 'string' && /^\d{1,2}:\d{2}/.test(endInput) ? endInput : endInput;
    return `${startInput} - ${endStr} น.`;
  }
  const s = new Date(startInput);
  const e = new Date(endInput);
  if (isNaN(s.getTime()) || isNaN(e.getTime())) return `${startInput} - ${endInput}`;

  const sH = String(s.getHours()).padStart(2, '0');
  const sM = String(s.getMinutes()).padStart(2, '0');
  const eH = String(e.getHours()).padStart(2, '0');
  const eM = String(e.getMinutes()).padStart(2, '0');

  return `${sH}:${sM} - ${eH}:${eM} น.`;
}

/**
 * จัดรูปแบบวันเวลาเต็ม เช่น "วันเสาร์ที่ 24 ต.ค. 2569 เวลา 09:00 - 12:00 น."
 * @param {string|Date} startInput 
 * @param {string|Date} endInput 
 * @returns {string}
 */
function formatThaiDateTimeRange(startInput, endInput) {
  if (!startInput) return '-';
  const s = new Date(startInput);
  if (isNaN(s.getTime())) return '-';

  const dayOfWeek = THAI_DAYS_FULL[s.getDay()];
  const dateStr = formatThaiDate(s);
  const timeRange = endInput ? formatThaiTimeRange(startInput, endInput) : formatThaiTime(startInput);

  return `${dayOfWeek}ที่ ${dateStr} เวลา ${timeRange}`;
}

/**
 * แปลงสตริง วันที่ (YYYY-MM-DD) และเวลา (HH:mm) ให้เป็น ISO 8601 (เขตเวลาไทย +07:00)
 * @param {string} dateStr YYYY-MM-DD
 * @param {string} timeStr HH:mm
 * @returns {string}
 */
function toBangkokISO(dateStr, timeStr) {
  return `${dateStr}T${timeStr}:00+07:00`;
}

/**
 * คำนวณความต่างเวลาเป็นนาที
 * @param {string|Date} start 
 * @param {string|Date} end 
 * @returns {number}
 */
function diffMinutes(start, end) {
  const s = new Date(start).getTime();
  const e = new Date(end).getTime();
  return Math.round((e - s) / 60000);
}

/**
 * ตรวจสอบว่าช่วงเวลา 2 ช่วงทับซ้อนกันหรือไม่ (Interval Overlap)
 * @param {string|Date} start1 
 * @param {string|Date} end1 
 * @param {string|Date} start2 
 * @param {string|Date} end2 
 * @returns {boolean}
 */
function isOverlapping(start1, end1, start2, end2) {
  const s1 = new Date(start1).getTime();
  const e1 = new Date(end1).getTime();
  const s2 = new Date(start2).getTime();
  const e2 = new Date(end2).getTime();
  return s1 < e2 && s2 < e1;
}


