    h5_require_chief_proctor: true,               // ทุกห้องต้องมีหัวหน้าห้อง 1 คน
    h5_require_academic_lead: true,               // กฎข้อ 4: หัวหน้าห้องต้องเป็นอาจารย์สายวิชาการ (Academic Lead)

    // กฎข้อ 2 & ข้อ 3: การเคารพวันสะดวกเฉพาะเจาะจงและรูปแบบกะ
